// Parse one ad insight row -> creative_daily row for yesterday
function actVal(arr, types){ if(!Array.isArray(arr)) return 0; for(const t of types){ const a=arr.find(x=>x.action_type===t); if(a&&a.value!=null) return parseFloat(a.value); } return 0; }
const PURCHASE=['omni_purchase','purchase','offsite_conversion.fb_pixel_purchase','app_custom_event.fb_mobile_purchase'];
const d=new Date(Date.now()-86400000);
const yest=`${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;
return $input.all().map(({json:a})=>{
  const spend=parseFloat(a.spend||0);
  const conversions=actVal(a.actions,PURCHASE);
  const revenue=actVal(a.action_values,PURCHASE);
  let roas=0;
  if(Array.isArray(a.purchase_roas)&&a.purchase_roas.length) roas=parseFloat(a.purchase_roas[0].value||0);
  else roas= spend>0 ? revenue/spend : 0;
  const videoPlays=actVal(a.video_play_actions,['video_view']);
  const thruplays=actVal(a.video_thruplay_watched_actions,['video_view']);
  return { json: {
    ad_id:a.ad_id,
    adset_id:a.adset_id,
    campaign_id:a.campaign_id,
    date:yest,
    spend:Math.round(spend*100)/100,
    revenue:Math.round(revenue*100)/100,
    impressions:parseInt(a.impressions||0),
    reach:parseInt(a.reach||0),
    clicks:parseInt(a.clicks||0),
    link_clicks:parseInt(a.inline_link_clicks||0),
    unique_link_clicks:parseInt(a.unique_inline_link_clicks||0),
    conversions:Math.round(conversions),
    frequency:Math.round(parseFloat(a.frequency||0)*100)/100,
    purchase_roas:Math.round(roas*10000)/10000,
    video_plays:Math.round(videoPlays),
    thruplays:Math.round(thruplays)
  }};
});
